from collections import deque

def paint_on_mask(x, maskcolor, seedcolors):
 h,w=x.shape; d=np.full((h,w),999,int); labels=np.empty((h,w),object); labels[:]=None; q=deque()
 for r,c0 in np.argwhere(x==maskcolor):
  r=int(r); c0=int(c0)
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   rr,cc=r+dr,c0+dc
   if 0<=rr<h and 0<=cc<w and x[rr,cc] in seedcolors:
    col=int(x[rr,cc]);
    if d[r,c0]>1: d[r,c0]=1; labels[r,c0]={col}; q.append((r,c0))
    elif d[r,c0]==1: labels[r,c0].add(col)
 while q:
  r,c0=q.popleft()
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   rr,cc=r+dr,c0+dc
   if 0<=rr<h and 0<=cc<w and x[rr,cc]==maskcolor:
    nd=d[r,c0]+1
    if nd<d[rr,cc]: d[rr,cc]=nd; labels[rr,cc]=set(labels[r,c0]);q.append((rr,cc))
    elif nd==d[rr,cc]: labels[rr,cc]|=labels[r,c0]
 out=x.copy()
 for r,c0 in np.argwhere(x==maskcolor):
  l=labels[r,c0]
  if l and len(l)==1: out[r,c0]=next(iter(l))
 return out,d,labels
